def transform(grid):
    """Shift all non-background cells down by one row, clipping at the bottom."""
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    h, w = len(grid), len(grid[0])
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != bg:
                out[r + 1][c] = grid[r][c]
    return out
